#!/usr/bin/env python3
"""Independent offline oracle for complete real public plate3MF workflow outputs."""
from pathlib import Path
import json,sys,math,hashlib,zipfile,io
from xml.etree import ElementTree as ET
from mesh import inspect,BOUNDS
ENGINE='sha256:32eec74e3019d9e2d767c9016f05aa3daa49441c6102423a269d67b9c7f02a08:abbf2aa02a6f2101c600aa1eedd20fa80ab2db206e677ca860d9c5103cdfbfcc'
IDENTITY=[1,0,0,0,1,0,0,0,1,0,0,0]
NS={'m':'http://schemas.microsoft.com/3dmanufacturing/core/2015/02'}
sha=lambda b:hashlib.sha256(b).hexdigest()
def derive(native,binding,diameter):
 assert native['format']=='codi-jsketcher-project'and native['version']==2 and native['unit']=='millimeter';project=native['project'];history=project['model']['history'];assert [x['type']for x in history]==['PLANE','WORKER_SELECTED_PROFILE_EXTRUDE_V2','WORKER_THROUGH_HOLES_V1'];plane,profile,hole=[x['params']for x in history];assert plane['orientation']=='XY'and plane['datum']is None and plane['depth']==0
 assert profile['faceId']==binding['faceId']and profile['regionId']==binding['regionId']and profile['featureId']==binding['profile']['featureId']and profile['engine']=='occ'and profile['engineRevision']==ENGINE and profile['unit']=='millimeter'and profile['depth']==20 and profile['bodyPolicy']=='separate'
 assert hole['kind']=='centered-through'and hole['diameter']==diameter and hole['featureId']==binding['hole']['featureId']and hole['engine']=='occ'and hole['engineRevision']==ENGINE and hole['sourceFaceId']==binding['faceId']and hole['sourceRegionId']==binding['regionId']and hole['sourceFeatureId']==profile['featureId']and hole['producerFeatureId']==profile['featureId']and hole['target']==binding['profile']['outputId']
 sketches=project['sketches'];assert len(sketches)==1 and sketches[0]['id']==binding['faceId'];source=sketches[0]['data'];assert source['metadata']['boundaryFrame']=={'origin':[0,0,0],'x':[1,0,0],'y':[0,1,0],'z':[0,0,1]};objects=source['objects'];assert len(objects)==4 and all(x['type']=='Segment'and x['role']is None for x in objects);ids=[x['id']for x in objects];assert len(set(ids))==4
 points=[];edges=set()
 for segment in objects:
  p,q=[tuple(segment['data'][k][axis]for axis in['x','y'])for k in['a','b']];assert all(math.isfinite(x)for x in p+q)and p!=q;points.extend([p,q]);key=tuple(sorted([p,q]));assert key not in edges;edges.add(key)
 xmin,ymin=map(min,zip(*points));xmax,ymax=map(max,zip(*points));assert(xmin,ymin,xmax,ymax)==(0,0,100,50);corners=[(xmin,ymin),(xmax,ymin),(xmax,ymax),(xmin,ymax)];expected={tuple(sorted([corners[i],corners[(i+1)%4]]))for i in range(4)};assert edges==expected
 discovery=binding['discovery'];assert discovery['faceId']==binding['faceId']and discovery['engineRevision']==ENGINE and discovery['unit']=='millimeter';regions=[x for x in discovery['regions']if x['regionId']==binding['regionId']];assert len(regions)==1 and regions[0]['support']=='supported'and set(regions[0]['descriptor']['outerCurveIds'])==set(ids)and regions[0]['descriptor']['holeCurveIds']==[]
 m=native['manufacturing'];assert m['version']==1 and m['unit']=='millimeter'and isinstance(m['revision'],str)and len(m['revision'])==71 and m['revision'].startswith('sha256-')and all(c in'0123456789abcdef'for c in m['revision'][7:]);assert m['materials']==[{'id':'pla','name':'PLA'}]and m['appearances']==[{'id':'blue','name':'Blue','color':'#3366ff'}];assert len(m['objects'])==len(m['bindings'])==1;part=m['objects'][0];assert part['id']=='plate'and part['name']=='Mounting plate'and len(part['regions'])==1;region=part['regions'][0];alias=m['bindings'][0];assert region['id']=='main'and region['bodyId']==alias['id']and alias['featureId']==hole['featureId']and alias['operationType']=='WORKER_THROUGH_HOLES_V1'and region['materialId']=='pla'and region['appearanceId']=='blue'and region['transform']==IDENTITY
 r=diameter/2;depth=profile['depth'];truth={'bounds':{'min':[xmin,ymin,plane['depth']],'max':[xmax,ymax,plane['depth']+depth]},'bores':[((xmin+xmax)/2,(ymin+ymax)/2,r)],'volume':((xmax-xmin)*(ymax-ymin)-math.pi*r*r)*depth}
 return{'truth':truth,'metadata':m,'source':source,'history':history,'producer':hole,'bodyId':binding['hole']['outputId'],'part':part}
def identity_transform(element):
 if'transform'in element.attrib:assert [float(x)for x in element.attrib['transform'].split()]==IDENTITY

def check3mf(file,truth):
 raw=file.read_bytes();assert len(raw)<=67108864
 with zipfile.ZipFile(io.BytesIO(raw))as z:
  names=z.namelist();assert len(names)==len(set(names))and set(names)=={'[Content_Types].xml','_rels/','_rels/.rels','3D/','3D/3dmodel.model'}and z.testzip()is None
  rel=ET.fromstring(z.read('_rels/.rels'));assert len(rel)==1 and rel[0].attrib['Target']=='/3D/3dmodel.model'and rel[0].attrib['Type']=='http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel';ct=ET.fromstring(z.read('[Content_Types].xml'));assert any(x.attrib.get('Extension')=='model'and x.attrib.get('ContentType')=='application/vnd.ms-package.3dmanufacturing-3dmodel+xml'for x in ct)
  xml=z.read('3D/3dmodel.model');assert len(xml)<=48*1024*1024;decl=dict(value for _,value in ET.iterparse(io.BytesIO(xml),events=['start-ns']));assert decl['codi']=='https://ksu.codes/3mf/metadata/2026';model=ET.fromstring(xml);assert model.attrib['unit']=='millimeter';md=model.findall('m:metadata',NS);assert len(md)==2;metadata={x.attrib['name']:x.text for x in md};assert set(metadata)=={'codi:SourceRevision','codi:ManufacturingBindings'};assert metadata['codi:SourceRevision']==truth['metadata']['revision'][7:];p=json.loads(metadata['codi:ManufacturingBindings']);assert p['version']==1 and p['revision']==metadata['codi:SourceRevision']and len(p['parts'])==len(p['materialPairs'])==1
  part=p['parts'][0];assert part['id']==truth['part']['id']and part['name']==truth['part']['name']and len(part['regions'])==1;region=part['regions'][0];assert region['id']=='main'and region['bodyId']==truth['bodyId']and region['featureId']==truth['producer']['featureId']and region['engine']=='occ'and region['engineRevision']==ENGINE and region['materialId']=='pla'and region['appearanceId']=='blue';pair=p['materialPairs'][0];assert pair['materialId']=='pla'and pair['appearanceId']=='blue'and pair['index']==region['materialIndex']==0
  resources=model.find('m:resources',NS);assert len(resources)==4;resourceIds=[int(x.attrib['id'])for x in resources];assert len(set(resourceIds))==4 and all(x>0 for x in resourceIds);objects={int(x.attrib['id']):x for x in resources.findall('m:object',NS)};assert len(objects)==3 and all(x.attrib['type']=='model'for x in objects.values());materials=resources.findall('m:basematerials',NS);assert len(materials)==1 and int(materials[0].attrib['id'])==pair['resourceId']==region['materialResourceId'];assert len(materials[0])==1 and materials[0][0].attrib=={'name':'PLA','displaycolor':'#3366FF'}
  build=model.find('m:build',NS);assert len(build)==1 and int(build[0].attrib['objectid'])==part['buildResourceId'];identity_transform(build[0]);group=objects[part['buildResourceId']];assert group.attrib['name']==part['name']and group.find('m:mesh',NS)is None;refs=group.find('m:components',NS);assert len(refs)==1 and int(refs[0].attrib['objectid'])==region['componentResourceId'];identity_transform(refs[0]);component=objects[region['componentResourceId']];assert component.attrib['name']=='main'and component.find('m:mesh',NS)is None;refs=component.find('m:components',NS);assert len(refs)==1 and int(refs[0].attrib['objectid'])==region['meshResourceId'];identity_transform(refs[0]);obj=objects[region['meshResourceId']];assert obj.attrib['name']=='main'and int(obj.attrib['pid'])==pair['resourceId']and int(obj.attrib['pindex'])==0 and obj.find('m:components',NS)is None
  mesh=obj.find('m:mesh',NS);vr=mesh.find('m:vertices',NS);tr=mesh.find('m:triangles',NS);assert all(set(x.attrib)=={'x','y','z'}for x in vr)and all(set(x.attrib)=={'v1','v2','v3'}for x in tr);vertices=[tuple(float(x.attrib[k])for k in['x','y','z'])for x in vr];triangles=[tuple(int(x.attrib[k])for k in['v1','v2','v3'])for x in tr]
 return {'file':file.name,'bytes':len(raw),'sha256':sha(raw),'provenance':p,'geometry':inspect(vertices,triangles,truth['truth'],truth['producer']['diameter']==10)}
def main(folder):
 receiptRaw=(folder/'receipt.json').read_bytes();receipt=json.loads(receiptRaw);assert receipt['status']=='PASS'and receipt['ownedContextClosed']and receipt['sharedBrowserDisconnectedOnly']and receipt['syntheticGeometry']is False and receipt['syntheticStorage']is False and receipt['filesystemRace']is False and receipt['driverPins']==receipt['driverPinsAfter'];rows=receipt['rows'];find=lambda label:next(x for x in rows if x['label']==label);binding=find('Actual public STEP part authored')['binding'];pinrows=[x for x in rows if x['label']=='Exact source-bound outer app and critical inner runtime'];assert len(pinrows)==3
 for row in pinrows:
  assert row['outer']['sha256']==receipt['pins']['outer']['sha256'];actual={x['name']:x['sha256']for x in row['files']};assert actual==receipt['pins']['files']
 natives={};nativeFiles={}
 for name in['material-plate','reopened-material-plate','edited-material-plate']:
  raw=(folder/(name+'.jsketcher.json')).read_bytes();row=find(name+' normal native Save and server sync');assert len(raw)==row['bytes']and sha(raw)==row['sha256'];natives[name]=json.loads(raw);nativeFiles[name]={'sha256':sha(raw),'bytes':len(raw)}
 assert (folder/'material-plate.jsketcher.json').read_bytes()==(folder/'reopened-material-plate.jsketcher.json').read_bytes();initial=derive(natives['material-plate'],binding,10);edited=derive(natives['edited-material-plate'],binding,14);assert initial['source']==edited['source'];expected=json.loads(json.dumps(initial['history']));expected[2]['params']['diameter']=14;assert expected==edited['history'];a=dict(initial['metadata']);b=dict(edited['metadata']);a.pop('revision');b.pop('revision');assert a==b and initial['metadata']['revision']!=edited['metadata']['revision']
 results=[]
 for label,truth in[('initial',initial),('edited',edited),('reopened',edited)]:
  row=find(label+' public 3MF export and matching browser/server bytes');r=check3mf(folder/(label+'.3mf'),truth);assert row['sha256']==r['sha256']and row['bytes']==r['bytes']and row['authoredStatePreserved'];commit=row['result'];assert commit['path']==row['file']and commit['persistence']=='browser'and commit['committed']is True and commit['dirty']is False and commit['serverStatus']=='not-verified'and isinstance(commit['version'],str)and commit['version'];r['commit']=commit;results.append(r)
 A,B,C=[r['geometry']for r in results];assert A['meshVolume']>B['meshVolume'];assert all(abs(B['meshBounds'][k][i]-C['meshBounds'][k][i])<=BOUNDS for k in['min','max']for i in range(3));assert abs(B['meshVolume']-C['meshVolume'])<=B['measuredSagBound']+C['measuredSagBound'];assert results[1]['provenance']==results[2]['provenance']
 print(json.dumps({'status':'PASS','scope':'Independent complete public workflow exported-artifact/source/mesh fixture oracle; no new Native execution, general nesting proof, slicer or physical print claim','receiptSha256':sha(receiptRaw),'runtimePins':receipt['pins'],'nativeFiles':nativeFiles,'exports':results,'editedReopened':{'sourceAndAssignmentIntentEqual':True,'canonicalOrientedTrianglesEqual':B['canonicalOrientedTriangleSha256']==C['canonicalOrientedTriangleSha256'],'meshVolumeDifference':abs(B['meshVolume']-C['meshVolume']),'equivalentWithinSourceDerivedMeshDomain':True},'meshArithmeticToleranceMM3':1e-6,'surfaceToleranceMm':1e-7,'meshWindingTolerance':1e-7,'future32HoleStatus':'NOT_RUN; shared mesh helper supports actual bore lists/Euler2-2N, saved-source/public receipt intake must be frozen for that workflow'},indent=2))
if __name__=='__main__':main(Path(sys.argv[1]).resolve())
